 */
public class Node_previousSibling_TriageGen1Test {

    private Document doc;

    @Before
    public void setUp() {
        doc = Document.createShell("");
    }









    /**
     * Test case where siblingIndex() might return null.
     * Since siblingIndex() returns int in standard Jsoup, but the provided code 
     * snippet uses Integer index and Validate.notNull(index), we simulate 
     * the scenario where the internal index logic might fail if it were an Integer.
     * However, in standard Jsoup, siblingIndex returns int. 
     * Given the provided implementation uses Integer index and Validate.notNull,
     * we assume the environment allows for a null index check.
     */
    @Test
    public void testPreviousSibling_StructureVerification() {
        // This test ensures the branching logic: (index > 0) vs (else)
        Element parent = doc.body();
        Element node1 = parent.appendElement("a");
        Element node2 = parent.appendElement("b");

        // Branch 1: index > 0
        assertEquals(node1, node2.previousSibling());

        // Branch 2: index == 0
        assertNull(node1.previousSibling());
    }
}
